func (suite *kadTemplateSuite) TestHIPRTeacherActivationEmail() {
	ktx := suite.KAContext()
	templateBytes, err := os.ReadFile(
		"../../districts/templates/emails/hipr_teacher_activation_email.gohtml",
	)
	suite.Require().NoError(err)

	emailData := EmailContextData{
		"district_provided_name": "Alex",
		"path":                   "/districts/activate",
		"query_params":           map[string]string{"udi": "test-udi-uuid"},
		"emailLanguage":          "en",
	}

	templateStr, emailSubject, renderErr := prepareHTMLEmail(
		ktx, string(templateBytes), emailData, []*graphql.SubTemplate(nil), "en")

	suite.Require().NoError(renderErr)
	suite.Require().Equal(
		"Khan Academy Districts - Welcome to your Free 90-Day Trial!",
		emailSubject)
	suite.Require().Contains(templateStr, "Hi Alex,")
	// Both the CTA button and the step-1 link must carry the activation flow
	// URL built from .path/.query_params.
	suite.Require().Contains(templateStr, "udi=test-udi-uuid")
	suite.Require().Contains(templateStr, "Confirm your account")
	// param+safe interpolation must emit live markup, not escaped text.
	suite.Require().Contains(templateStr, "<b>Add a new class</b>")
	suite.Require().NotContains(templateStr, "&lt;b&gt;")
	// The divider is defined in this file, not in kad_template.
	suite.Require().Contains(templateStr, "border-top: 1px solid #E0E1EE")
	suite.Require().Contains(templateStr,
		"district-teacher-emails/hipr_teacher_create_class.png")
}

func _mapErrorToAllClassrooms(
	errorCode graphql.WritingCoachConfigErrorCode,
	result *graphql.CreateWritingCoachAssignmentsResult,
) *graphql.CreateWritingCoachAssignmentsResult {
	// `classrooms: []` is a legal input, and Errors is sized from it, so
	// without this there is no slot to report a whole-request failure in and
	// every error path would look like a success to the client.
	if len(result.Errors) == 0 {
		result.Errors = []*graphql.WritingCoachConfigError{{Code: errorCode}}
		return result
	}
	for i := range result.Errors {
		if result.Errors[i] == nil {
			result.Errors[i] = &graphql.WritingCoachConfigError{}
		}
		result.Errors[i].Code = errorCode
	}
	return result
}

func _mapErrorToAllClassrooms(
	errorCode graphql.WritingCoachConfigErrorCode,
	result *graphql.CreateWritingCoachAssignmentsResult,
) *graphql.CreateWritingCoachAssignmentsResult {
	if len(result.Errors) == 0 {
		// No classrooms were requested, but the mutation still failed. Report
		// one error anyway so the client can tell this apart from success.
		result.Errors = []*graphql.WritingCoachConfigError{{Code: errorCode}}
