	if attempt.WordPair != "" && _attemptAllCorrect(attempt) {
		correctCounts[attempt.WordPair]++
	}
case attempt.ChallengeType != "":
	// Warm attempt of another type — not part of this type's set.
default:
	// Cold attempt — missing challenge_type.
	cold = append(cold, attempt)
