switch {
case attempt.ChallengeType != "":
	// Warm (migrated). Count only matching-type attempts that carry a
	// pair; a matching-type attempt with no pair is warm-and-pairless,
	// not cold, so it must not be re-backfilled.
	if attempt.ChallengeType == challengeType &&
		attempt.WordPair != "" && _attemptAllCorrect(attempt) {
		correctCounts[attempt.WordPair]++
	}
default:
